{
  "test_cases": [
    {
      "id": "TC-038-01",
      "title": "Disabling multiple authenticators after threshold reached",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and a second factor (e.g., TOTP) enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records the failure for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the failed login attempt with incorrect password and incorrect second factor code until the threshold (5 attempts) is reached.",
          "expected": "After the 5th consecutive failure, the system disables both the password authenticator and the second factor authenticator for the account."
        },
        {
          "no": 3,
          "action": "Attempt login again with the correct password and correct second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled. The user is informed that the account requires administrative intervention or reset."
        }
      ]
    },
    {
      "id": "TC-038-02",
      "title": "No disabling when threshold is not reached",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and a second factor enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and an incorrect second factor code 4 times consecutively.",
          "expected": "Authentication fails each time. The system records the failures but does not disable any authenticators."
        },
        {
          "no": 2,
          "action": "Attempt login with the correct password and correct second factor code.",
          "expected": "Authentication succeeds. The user logs in successfully, confirming that the authenticators remain active."
        }
      ]
    },
    {
      "id": "TC-038-03",
      "title": "Disabling only involved authenticators when one factor is correct",
      "covers": [
        "KDH-038"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and a second factor enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, correct second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures. The system tracks failures per authenticator involved in the failed attempt.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and a correct second factor code 5 times consecutively.",
          "expected": "Authentication fails each time due to the incorrect password. The system records failures for the password authenticator. The second factor authenticator is not involved in the failure (as it was correct) and should not be disabled if the logic strictly disables only 'involved' failed authenticators. However, if the requirement implies disabling all authenticators on the account upon reaching the threshold for the account, both may be disabled. Based on 'disable all of the authenticators involved', only the password should be disabled if the second factor was correct. Let's assume the system disables the specific authenticator that failed. If the requirement means 'all authenticators on the account', the test expectation changes. Given 'involved in consecutive failed authentication attempts', it implies the ones that were part of the failed attempt. If the second factor was correct, it wasn't the cause of failure, but it was 'involved' in the attempt. NIST 800-63B-4 §3.2.2 typically suggests locking the account or disabling the specific factor. Let's stick to the literal interpretation: 'disable all of the authenticators involved'. If the second factor was correct, it was involved in the attempt. So both might be disabled. Let's refine the test to be clearer: Use incorrect password and incorrect second factor to ensure both are 'involved' in the failure. The previous test TC-038-01 covers this. This test case is ambiguous if one factor is correct. Let's change this test case to verify that if the threshold is reached, the account is locked/disabled such that no login is possible, regardless of which specific factor failed, to ensure security. Actually, the requirement says 'disable all of the authenticators involved'. If I enter wrong password and right OTP, the password is involved in the failure. The OTP is involved in the attempt but not the failure. Let's assume 'involved' means 'used in the failed attempt'. So both are disabled. Let's test that."
        },
        {
          "no": 2,
          "action": "Attempt login with the correct password and correct second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled."
        }
      ]
    }
  ]
}

