{
  "test_cases": [
    {
      "id": "TC-038-01",
      "title": "Disabling multiple authenticators after threshold reached",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and a second factor (e.g., TOTP) enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records the failure for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the failed login attempt with incorrect password and incorrect second factor code until the threshold (5 attempts) is reached.",
          "expected": "After the 5th consecutive failure, the system disables both the password authenticator and the second factor authenticator for the account."
        },
        {
          "no": 3,
          "action": "Attempt login again with the correct password and correct second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled. The user is informed that the account requires administrative intervention or reset."
        }
      ]
    },
    {
      "id": "TC-038-02",
      "title": "No disabling when threshold is not reached",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and a second factor enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and an incorrect second factor code 4 times consecutively.",
          "expected": "Authentication fails each time. The system records the failures but does not disable the password or second factor authenticators."
        },
        {
          "no": 2,
          "action": "Attempt login with the correct password and correct second factor code.",
          "expected": "Authentication succeeds. The user logs in successfully."
        }
      ]
    },
    {
      "id": "TC-038-03",
      "title": "Disabling only involved authenticators when one factor is correct",
      "covers": [
        "KDH-038"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and a second factor enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, correct second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures. The system tracks failures per authenticator involved in the failed attempt.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and a correct second factor code 5 times consecutively.",
          "expected": "Authentication fails each time due to the incorrect password. The system records failures for the password authenticator. The second factor authenticator is not considered 'failed' in the context of the threshold if it was provided correctly, or if the requirement implies disabling only those that contributed to the failure, only the password authenticator is disabled. (Note: If the system treats any failed login as a failure for all presented authenticators, both would be disabled. Based on 'authenticators involved in consecutive failed authentication attempts', if the second factor was correct, it did not cause the failure. However, standard interpretation of 'involved' in multi-factor failure often means all factors presented in the failed attempt. Let's assume the stricter interpretation that all presented authenticators in the failed attempt are 'involved'.) Correction: The requirement says 'authenticators involved in consecutive failed authentication attempts'. If I provide a correct 2FA but wrong password, the 2FA was involved in the attempt. If the threshold is reached, all involved authenticators are disabled. So both should be disabled."
        },
        {
          "no": 2,
          "action": "Attempt login again with the correct password and correct second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled."
        }
      ]
    }
  ]
}

