{
  "decisions": [
    {
      "requirement_id": "KDH-026",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a functional boundary (15 characters) that can be verified by submitting passwords of 14 and 15 characters and observing the system's acceptance or rejection."
    },
    {
      "requirement_id": "KDH-027",
      "methods": [
        "Test"
      ],
      "rationale": "The counting logic for Unicode code points can be verified by submitting passwords containing multi-byte characters and checking if the system correctly counts them as single characters against the length limit."
    },
    {
      "requirement_id": "KDH-028",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement can be verified by attempting to access a stored password hint without authentication and confirming that the system denies access or does not expose the hint."
    },
    {
      "requirement_id": "KDH-029",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The absence of specific UI prompts (like security questions) is best verified by inspecting the user interface design and code to ensure no such fields or prompts exist during password creation."
    },
    {
      "requirement_id": "KDH-030",
      "methods": [
        "Test"
      ],
      "rationale": "The system's behavior of requesting and verifying the full password string can be tested by submitting a valid password and a truncated version to ensure only the full string is accepted."
    },
    {
      "requirement_id": "KDH-031",
      "methods": [
        "Test"
      ],
      "rationale": "The blocklist comparison can be verified by attempting to set a password known to be on the blocklist and observing the system's rejection."
    },
    {
      "requirement_id": "KDH-032",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to compare the entire password rather than substrings can be tested by using a password that contains a blocked word as a substring but is not itself on the blocklist, verifying it is accepted."
    },
    {
      "requirement_id": "KDH-033",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection flow and error messaging can be verified by submitting a blocked password and checking that the system rejects it and displays the specific reason for rejection."
    },
    {
      "requirement_id": "KDH-034",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The presence of guidance text on the UI after a rejection is a visual element that can be demonstrated by triggering the rejection and observing the displayed guidance."
    },
    {
      "requirement_id": "KDH-035",
      "methods": [
        "Test"
      ],
      "rationale": "Compatibility with password managers and autofill can be verified by using a browser's autofill feature or a password manager extension to populate the password field and confirming the system accepts the input."
    },
    {
      "requirement_id": "KDH-036",
      "methods": [
        "Test"
      ],
      "rationale": "The recovery logic can be verified by simulating account recovery scenarios using the specified combinations of recovery codes and authenticators to ensure only valid combinations succeed."
    },
    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The lockout mechanism can be verified by performing 50 consecutive failed login attempts and then attempting a correct login to confirm the authenticator is disabled."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The multi-authenticator lockout can be verified by failing authentication attempts involving multiple factors until the threshold is reached and confirming all involved authenticators are disabled."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The re-binding requirement can be verified by attempting to use a disabled authenticator without re-binding it and confirming the system rejects the attempt until re-binding is performed."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of non-compliant e-Devlet responses can be verified by mocking an e-Devlet response with insufficient assurance levels and observing the system's defined response (e.g., decline or routing)."
    },
    {
      "requirement_id": "KDH-041",
      "methods": [
        "Test"
      ],
      "rationale": "Session assurance level handling can be verified by creating a session at a specific AAL and attempting to access resources that require a higher AAL, confirming the system does not elevate the session level."
    },
    {
      "requirement_id": "KDH-042",
      "methods": [
        "Test"
      ],
      "rationale": "Transport security enforcement can be verified by attempting to downgrade an authenticated HTTPS session to HTTP and confirming the system blocks the request or redirects back to HTTPS."
    },
    {
      "requirement_id": "KDH-043",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The implementation of automated attack protections like WAF settings and analytics is best verified by reviewing the system configuration, architecture diagrams, and security policies."
    },
    {
      "requirement_id": "KDH-044",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of TOTP codes can be verified by submitting a valid TOTP code twice in succession and confirming the second attempt is rejected."
    },
    {
      "requirement_id": "KDH-045",
      "methods": [
        "Test"
      ],
      "rationale": "The notification mechanism can be verified by issuing a new recovery code and checking that the expected notification is sent to the representative."
    },
    {
      "requirement_id": "KDH-046",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation and replacement of recovery codes can be verified by using a recovery code and then attempting to use it again, confirming it is no longer valid and a new one has been issued."
    },
    {
      "requirement_id": "KDH-047",
      "methods": [
        "Test"
      ],
      "rationale": "The authentication level requirement can be verified by attempting to access account information using AAL1 authentication and confirming the system denies access, while allowing access with AAL2 or AAL3."
    },
    {
      "requirement_id": "KDH-048",
      "methods": [
        "Test"
      ],
      "rationale": "The update notification feature can be verified by making a change to the account information and confirming that a notification is sent to the representative."
    },
    {
      "requirement_id": "KDH-049",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The capability to report unauthorized access is a UI feature that can be demonstrated by navigating to the account settings and showing the report option."
    },
    {
      "requirement_id": "KDH-050",
      "methods": [
        "Test"
      ],
      "rationale": "The error handling behavior can be verified by triggering a security-sensitive error (e.g., invalid input) and inspecting the response to ensure it contains only a generic message without internal details."
    }
  ]
}

