      "preconditions": "A company representative account exists with password and a second factor (e.g., TOTP) enabled. The account is not currently locked or disabled.",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for failed attempts defined in VBP Software Design Document §14 is 5 consecutive failures.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records the failure for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the failed login attempt with incorrect password and incorrect second factor code until the threshold (5 attempts) is reached.",
          "expected": "After the 5th consecutive failed attempt, the system disables both the password authenticator and the second factor authenticator for the account."
        },
        {
          "no": 3,
          "action": "Attempt login again with the correct password and a valid second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled. The user is informed that the account requires administrative intervention or reset."
        }
      ]
    },
    {
      "id": "TC-038-02",
      "title": "Disabling authenticators when threshold is reached with mixed failures",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and a second factor enabled. The account is active.",
      "test_inputs": "Valid username, incorrect password, correct second factor code; then incorrect password and incorrect second factor code.",
      "assumptions": "The threshold for failed attempts is 5. 'Consecutive failed authentication attempts' implies that any failure in the multi-factor sequence counts towards the threshold for the involved authenticators.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username, incorrect password, and correct second factor code.",
          "expected": "Authentication fails. The password authenticator is marked as failed. The second factor is not marked as failed because it was correct."
        },
        {
          "no": 2,
          "action": "Attempt login with valid username, incorrect password, and incorrect second factor code.",
          "expected": "Authentication fails. Both password and second factor are marked as failed."
        },
        {
          "no": 3,
          "action": "Continue attempting login with incorrect password and incorrect second factor code until the total consecutive failed attempts reach the threshold (5).",
          "expected": "The system disables both the password and the second factor authenticators, as both were involved in the consecutive failed attempts that reached the threshold."
        }
      ]
    },
    {
      "id": "TC-038-03",
